#ifndef GUARD_STRATA_MAP_H
#define GUARD_STRATA_MAP_H

#include "constants/strata.h"

// Per-map Strata data, one row per Strata map, generated by tools/strata/gen_maps.py
// from the `era=`, `habitat=` and `light=` keys in tools/strata/maps/ into
// src/data/strata_map_eras.h (sStrataMapInfo).
struct StrataMapInfo
{
    u16 map;     // MAP_STRATA_* (group << 8 | num)
    u8 era;      // enum StrataEra; ERA_COUNT for the present-day hub, which has none
    u8 habitat;  // enum SelectionPressure (FOREST/OPEN/WATER), or PRESSURE_NONE
    u8 light;    // enum StrataLight
};

// The row of a map (MAP_* constant), or NULL if it isn't a Strata map.
const struct StrataMapInfo *Strata_GetMapInfo(u16 map);

// The current map's era (enum StrataEra), or ERA_COUNT outside deep-time maps.
u32 Strata_GetMapEra(void);

// The current map's habitat tag: PRESSURE_FOREST, _OPEN or _WATER, or PRESSURE_NONE
// (untagged: habitat then comes from the grass underfoot, see Selection_GetHabitat).
enum SelectionPressure Strata_GetMapHabitat(void);

// The current map's fixed lighting, or STRATA_LIGHT_DNS (wall clock) if it has none.
enum StrataLight Strata_GetMapLight(void);

// The clock time a fixed light shows as (for UpdateTimeOfDay). FALSE for
// STRATA_LIGHT_DNS and STRATA_LIGHT_NONE, which have none.
bool32 Strata_GetLightTime(enum StrataLight light, s32 *hours, s32 *minutes);

#endif // GUARD_STRATA_MAP_H
